@helion.kernel()
def wide_f64_add_relu2(x, y):
    out = torch.empty_like(x)
    for tm, tn in hl.tile(x.size()):
        a = x[tm, tn].to(torch.float32)
        b = y[tm, tn].to(torch.float32)
        s = a + b
        r = torch.where(s > 0, s, torch.zeros_like(s))
        out[tm, tn] = (r * r).to(out.dtype)
    return out


